import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None:
        start = 0.0
    if horizon is None:
        rec_end = recorded_end(doc, scope)
        horizon = rec_end if rec_end is not None else 127.0

    state = {}
    properties = {}
    scheduled_entries = {}

    # First pass: collect properties and schedule future entries
    for inp in inputs:
        kind = inp.get("kind")
        t = inp.get("time")
        entities = inp.get("entities", [])
        if not entities:
            continue
        obj_id = entities[0]

        if kind == "Object Properties":
            properties[obj_id] = inp.get("fields", {})
        elif kind in ("Entry", "Initial View"):
            if t is not None and t > start:
                frame = int(t)
                if frame not in scheduled_entries:
                    scheduled_entries[frame] = []
                scheduled_entries[frame].append({
                    "obj_id": obj_id,
                    "vx": float(inp["fields"].get("vx", 0.0)),
                    "vy": float(inp["fields"].get("vy", 0.0)),
                    "x": float(inp["fields"].get("x", 0.0)),
                    "y": float(inp["fields"].get("y", 0.0))
                })

    # Second pass: initialise state at `start` from records at or before `start`
    for inp in inputs:
        kind = inp.get("kind")
        t = inp.get("time")
        entities = inp.get("entities", [])
        if not entities: continue
        obj_id = entities[0]

        if t is not None and 0 <= t <= start:
            if kind == "Initial State":
                state[obj_id] = {
                    "x": float(inp["fields"].get("x", 0.0)),
                    "y": float(inp["fields"].get("y", 0.0)),
                    "vx": float(inp["fields"].get("vx", 0.0)),
                    "vy": float(inp["fields"].get("vy", 0.0)),
                    "active": True,
                    "stationary": False
                }
            elif kind in ("Entry", "Initial View"):
                if obj_id not in state:
                    state[obj_id] = {
                        "x": float(inp["fields"].get("x", 0.0)),
                        "y": float(inp["fields"].get("y", 0.0)),
                        "vx": float(inp["fields"].get("vx", 0.0)),
                        "vy": float(inp["fields"].get("vy", 0.0)),
                        "active": True,
                        "stationary": False
                    }

    outcomes = []
    current_frame = int(start)

    while current_frame <= int(horizon):
        # 1. Apply scheduled entries for this frame
        if current_frame in scheduled_entries:
            for entry in scheduled_entries[current_frame]:
                obj_id = entry["obj_id"]
                state[obj_id] = {
                    "x": entry["x"],
                    "y": entry["y"],
                    "vx": entry["vx"],
                    "vy": entry["vy"],
                    "active": True,
                    "stationary": False
                }
                properties.setdefault(obj_id, {})

        collided_this_frame = set()

        # 2. Update positions and apply friction
        for obj_id, s in state.items():
            if not s["active"]:
                continue

            speed_sq = s["vx"]**2 + s["vy"]**2
            if speed_sq < 0.1**2:
                s["vx"], s["vy"] = 0.0, 0.0
                s["stationary"] = True
                continue

            mat = properties.get(obj_id, {}).get("material", "metal")
            # Estimated friction factors from recorded deceleration
            friction = 0.996 if mat == "metal" else 0.993

            s["x"] += s["vx"]
            s["y"] += s["vy"]
            s["vx"] *= friction
            s["vy"] *= friction

            if s["vx"]**2 + s["vy"]**2 < 0.1**2:
                s["vx"], s["vy"] = 0.0, 0.0
                s["stationary"] = True

        # 3. Check collisions
        obj_ids = list(state.keys())
        for i in range(len(obj_ids)):
            for j in range(i+1, len(obj_ids)):
                oid1, oid2 = obj_ids[i], obj_ids[j]
                s1, s2 = state[oid1], state[oid2]
                if not (s1["active"] and s2["active"]):
                    continue

                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist_sq = dx*dx + dy*dy

                # Collision threshold estimated from recorded distances (~0.41-0.47)
                if dist_sq < 0.45**2 and dist_sq > 1e-6:
                    dist = math.sqrt(dist_sq)
                    nx, ny = dx/dist, dy/dist

                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    v_rel_n = dvx*nx + dvy*ny

                    # Only resolve if approaching
                    if v_rel_n > 0: 
                        # Elastic collision approximation (equal mass baseline)
                        s1["vx"] -= v_rel_n * nx
                        s1["vy"] -= v_rel_n * ny
                        s2["vx"] += v_rel_n * nx
                        s2["vy"] += v_rel_n * ny

                        s1["stationary"] = False
                        s2["stationary"] = False

                        pair = tuple(sorted([oid1, oid2]))
                        if pair not in collided_this_frame:
                            collided_this_frame.add(pair)
                            outcomes.append({
                                "time": float(current_frame),
                                "kind": "Collision",
                                "entities": [oid1, oid2],
                                "value": None,
                                "src": None
                            })

        current_frame += 1

    return outcomes

