        lines = events_node.get("lines", [])
        for line_idx, line in enumerate(lines):
            match = re.match(r"Frame (\d+):\s*Object (\d+).*?(enters the scene|is in view when the video begins)", line)
            if match:
                frame = float(match.group(1))
                obj_id = f"Object {match.group(2)}"
                event_type = match.group(3)
                inputs_list.append({
                    "id": f"entry_{obj_id}_{int(frame)}",
                    "time": frame,
                    "kind": "Entry" if "enters" in event_type else "Initial View",
                    "entities": [obj_id],
                    "fields": {"event": event_type},
                    "src": [[events_node.get("node_id"), line_idx]]
                })

    # 3. Initial States from Motion Log (frame 0)
    if motion_node and motion_node.get("kind") == "table":
        rows = table_rows(motion_node)
        for row_idx, row_data in rows:
            frame_val = float(row_data.get("frame", "-1"))
            if frame_val == 0:
                obj_col = row_data.get("object", "")
                obj_match = re.match(r"(\d+)", obj_col)
                if obj_match:
                    obj_id = f"Object {obj_match.group(1)}"
                    fields = {}
                    for col in ['x', 'y', 'vx', 'vy', 'speed']:
                        val = row_data.get(col, "")
                        try:
                            fields[col] = float(val)
                        except ValueError:
                            pass
                    inputs_list.append({
                        "id": f"init_state_{obj_id}",
                        "time": 0.0,
                        "kind": "Initial State",
                        "entities": [obj_id],
                        "fields": fields,
                        "src": [[motion_node.get("node_id"), row_idx]]
                    })

    return inputs_list

def outcomes(doc, scope) -> List[Dict]:
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    children_nodes = [node_by_id(doc, cid) for cid in scope_node.get("children", [])]
    events_node = None
    for node in children_nodes:
        if ": Events" in node.get("title", ""):
            events_node = node
            break

    outcomes_list = []

    if events_node and events_node.get("kind") == "list":
        lines = events_node.get("lines", [])
        for line_idx, line in enumerate(lines):
            # Collision
            col_match = re.match(r"Frame (\d+):\s*(Object \d+).*collides with (Object \d+)", line)
            if col_match:
                outcomes_list.append({
                    "time": float(col_match.group(1)),
                    "kind": "Collision",
                    "entities": [col_match.group(2), col_match.group(3)],
                    "value": None,
                    "src": [[events_node.get("node_id"), line_idx]]
                })
                continue

            # Exit
            exit_match = re.match(r"Frame (\d+):\s*(Object \d+).*exits the scene", line)
            if exit_match:
                outcomes_list.append({
                    "time": float(exit_match.group(1)),
                    "kind": "Exit",
                    "entities": [exit_match.group(2)],
                    "value": None,
                    "src": [[events_node.get("node_id"), line_idx]]
                })
                continue

    return outcomes_list

def params(doc, scope) -> Dict[str, float]:
    return {}


# ---- step 2: forward model ----
import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None:
        start = 0.0
    if horizon is None:
        rec_end = recorded_end(doc, scope)
        horizon = rec_end if rec_end is not None else 127.0

    SCALE = 36.0
    COLLISION_THRESHOLD_SQ = 0.44**2
    RESTITUTION = 0.25

    properties = {}
    entries = {}

    for inp in inputs:
        kind = inp.get("kind")
        t = inp.get("time")
        entities = inp.get("entities", [])
        if not entities:
            continue
        obj_id = entities[0]

        if kind == "Object Properties":
            properties[obj_id] = inp.get("fields", {})
        elif kind in ("Entry", "Initial View"):
            if t is not None:
                entries[obj_id] = t

    # Read motion log from document
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    children_nodes = [node_by_id(doc, cid) for cid in scope_node.get("children", [])]
    motion_node = None
    for node in children_nodes:
        if ": Motion log" in node.get("title", ""):
            motion_node = node
            break

    motion_rows = []
    if motion_node:
        motion_rows = table_rows(motion_node)

    # Pre-process motion rows by object
    motion_by_obj = {}
    for row_idx, row_data in motion_rows:
        frame = float(row_data.get("frame", "-1"))
        obj_col = row_data.get("object", "")
        match = re.match(r"(\d+)", obj_col)
        if match:
            obj_id = f"Object {match.group(1)}"
            if obj_id not in motion_by_obj:
                motion_by_obj[obj_id] = []
            motion_by_obj[obj_id].append((frame, row_data))

    def get_latest_state(obj_id, max_frame):
        rows = motion_by_obj.get(obj_id, [])
        best = None
        for frame_val, row_data in rows:
            if frame_val <= max_frame:
                if best is None or frame_val > best[0]:
                    best = (frame_val, row_data)
        if best:
            return {
                "x": float(best[1].get("x", 0)),
                "y": float(best[1].get("y", 0)),
                "vx": float(best[1].get("vx", 0)),
                "vy": float(best[1].get("vy", 0))
            }
        return None

    # Build state at start from motion log
    state = {}
    for obj_id, entry_frame in entries.items():
        if start >= entry_frame:
            s = get_latest_state(obj_id, start)
            if s:
                state[obj_id] = s

    outcomes = []
    current_frame = int(start)

    while current_frame <= int(horizon):
        # Check for new entries at this frame
        for obj_id, entry_frame in entries.items():
            if int(entry_frame) == current_frame and obj_id not in state:
                s = get_latest_state(obj_id, current_frame)
                if s:
                    state[obj_id] = s

        collided_this_frame = set()

        # Check collisions first (at current state)
        obj_ids = list(state.keys())
        for i in range(len(obj_ids)):
            for j in range(i+1, len(obj_ids)):
                oid1, oid2 = obj_ids[i], obj_ids[j]
                s1, s2 = state[oid1], state[oid2]

                dx = s2["x"] - s1["x"]
                dy = s2["y"] - s1["y"]
                dist_sq = dx*dx + dy*dy

                if dist_sq < COLLISION_THRESHOLD_SQ and dist_sq > 1e-6:
                    dist = math.sqrt(dist_sq)
                    nx, ny = dx/dist, dy/dist

                    dvx = s1["vx"] - s2["vx"]
                    dvy = s1["vy"] - s2["vy"]
                    v_rel_n = dvx*nx + dvy*ny

                    if v_rel_n > 0:
                        impulse = (1 + RESTITUTION) / 2 * v_rel_n
                        s1["vx"] -= impulse * nx
                        s1["vy"] -= impulse * ny
                        s2["vx"] += impulse * nx
                        s2["vy"] += impulse * ny

                        pair = tuple(sorted([oid1, oid2]))
                        if pair not in collided_this_frame:
                            collided_this_frame.add(pair)
                            outcomes.append({
                                "time": float(current_frame),
                                "kind": "Collision",
                                "entities": [oid1, oid2],
                                "value": None,
                                "src": None
                            })

        # Update positions and apply friction
        for obj_id, s in state.items():
            speed_sq = s["vx"]**2 + s["vy"]**2
            if speed_sq < 0.01:
                s["vx"], s["vy"] = 0.0, 0.0
                continue

            mat = properties.get(obj_id, {}).get("material", "metal")
            shape = properties.get(obj_id, {}).get("shape", "sphere")

            fc = 0.005 if mat == "metal" else 0.002
            if shape == "cylinder":
                fc *= 1.5

            s["x"] += s["vx"] / SCALE
            s["y"] += s["vy"] / SCALE
            s["vx"] *= (1 - fc)
            s["vy"] *= (1 - fc)

        current_frame += 1

    return outcomes
